def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_prev = 0
    desperate_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                b = prev.get('bid', 0)
                prev_bids.append(b)
                if b >= DAILY_SALARY * 0.85:
                    strong_prev += 1

    if budget <= 0:
        return 0

    if not alive:
        return min(budget, DAILY_SALARY * 0.35)

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else DAILY_SALARY * 0.45

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if slots >= 2:
        base = DAILY_SALARY * 0.34
        if strong_prev >= 2:
            base = max(base, avg_prev * 0.72)
        elif highest_prev > 0:
            base = max(base, min(highest_prev * 0.68, DAILY_SALARY * 0.62))
    else:
        base = DAILY_SALARY * 0.62
        if highest_prev > 0:
            base = max(base, highest_prev + 2.0)

    if desperate_opp >= 2:
        base += 6
    elif desperate_opp == 1:
        base += 3

    if urgency >= 5:
        bid = max(base, DAILY_SALARY * 0.96)
    elif urgency >= 3:
        bid = max(base, DAILY_SALARY * 0.78)
    elif urgency >= 1:
        bid = max(base, DAILY_SALARY * 0.56)
    else:
        bid = base

    if day >= 8 and hp >= 6 and no_water_days == 0:
        bid *= 0.9

    if budget < DAILY_SALARY * 0.8:
        bid = min(bid, budget)
    else:
        bid = min(bid, budget, DAILY_SALARY * 1.25)

    if bid < 0:
        bid = 0
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from immediate previous_trace only
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate urgency: if we have low HP or already have no-water streak, bid more.
    urgency = 0.0
    if hp <= 2.5:
        urgency += 1.0
    if hp <= 4.0:
        urgency += 0.6
    if no_water_days >= 2:
        urgency += 0.8
    if no_water_days >= 3:
        urgency += 1.2

    # Supply scaling: with higher supply, we can afford slightly less aggressive bidding.
    # Map supply to [0,1] where 0 at MIN_SUPPLY and 1 at MAX_SUPPLY.
    if MAX_SUPPLY == MIN_SUPPLY:
        supply_factor = 0.5
    else:
        supply_factor = (supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
        if supply_factor < 0.0:
            supply_factor = 0.0
        if supply_factor > 1.0:
            supply_factor = 1.0

    # Target bid baseline.
    # If someone previously bid very high, we must respect that (avoid losing to them).
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Alex/Eric-like behavior; bid enough to compete, but not max out.
        base = DAILY_SALARY * (0.38 + 0.25 * urgency)  # up to ~0.63*salary
        # If our budget is large, slightly raise toward their pressure.
        if budget >= DAILY_SALARY * 1.2:
            base = max(base, min(budget, highest_prev_bid * 0.55))
    else:
        # Lower competitive pressure; bid moderately to secure water.
        base = DAILY_SALARY * (0.30 + 0.20 * urgency)  # up to ~0.50*salary
        # If supply is low, increase a bit.
        if supply <= float(MIN_SUPPLY) + 1.0:
            base *= 1.10

    # Convert baseline to an actionable bid with budget cap.
    # Also keep a small floor to avoid being undercut when stakes are high.
    bid_floor = DAILY_SALARY * (0.25 if hp > 4 else 0.55)
    bid = max(bid_floor, base)

    # If our HP is critical, push higher.
    if hp <= 1.5:
        bid = max(bid, DAILY_SALARY * 0.85)

    # Ensure bid does not exceed budget.
    if bid > budget:
        bid = budget

    # Never negative.
    if bid < 0.0:
        bid = 0.0

    return float(bid)
